//! The CLI's view of the config schema: one static tree, generated by
//! `#[derive(Cli)]` (`nos-proto-derive`) from the schema structs themselves,
//! so a field reaches the shell exactly as it is declared — its words, its
//! aliases, its sugar and its help `Topic` all sit in the field's `#[cli]`
//! attribute, which the derive makes mandatory.
//!
//! The REST segment of a field (`config_path::field_segment`) is always an
//! accepted spelling; `words` only adds today's CLI spelling, shown first.
//! Help text stays in `nos-config` (`Request::Describe` on the `Topic`).

use serde_json::Value;

use crate::Topic;

/// A generic config verb. `edit` never reaches a sugar function.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Verb {
    Set,
    Delete,
}

/// A sugar word's handler: the words after it, and the JSON of the object
/// that holds the field, in; the edit out. `None`: not this sugar — the
/// words are read as the plain field instead, if they can be.
pub type SugarFn = fn(Verb, &[&str], &Value) -> Option<SugarOut>;

/// What a sugar word means.
#[derive(Debug, Clone, PartialEq)]
pub enum SugarOut {
    /// The field's new JSON value (`Value::Null` clears an `Option`).
    Value(Value),
    /// These words instead, read at the same object.
    Words(Vec<String>),
}

/// Extra syntax for one field, declared on it: `word` edits the field
/// through `with` instead of the generic value rules.
#[derive(Debug)]
pub struct Sugar {
    pub word: &'static str,
    pub topic: Topic,
    pub with: SugarFn,
}

/// One field of a struct (or of an enum's struct variant).
#[derive(Debug)]
pub struct Field {
    /// The serde field name.
    pub name: &'static str,
    /// CLI help; `None` on a list key (the list's own topic covers it) and
    /// on an enum variant's fields.
    pub topic: Option<Topic>,
    /// Derived, read-only state: never edited from the CLI.
    pub hidden: bool,
    /// The field identifying a list element (see `config_path::ELEMENT_KEYS`).
    pub key: bool,
    /// Today's CLI spelling, when it differs from the REST segment.
    pub words: Option<&'static str>,
    /// Further accepted spellings, never shown.
    pub aliases: &'static [&'static str],
    pub sugar: &'static [Sugar],
    /// Key-token rewrites for a list field, `"{a}.{b} => {a} x {b}"`: a key
    /// shaped like the left side is read as the words on the right.
    pub templates: &'static [&'static str],
    pub kind: fn() -> Kind,
}

/// A struct: its fields, and its `Default` as JSON (a new list element, or
/// a struct value's starting point) — `None` for `#[cli(no_default)]`.
#[derive(Debug)]
pub struct Node {
    pub fields: &'static [Field],
    pub default: Option<fn() -> Value>,
}

#[derive(Debug)]
pub enum Payload {
    Unit,
    Newtype(fn() -> Kind),
    Struct(&'static [Field]),
}

/// One enum variant (serde's externally tagged form).
#[derive(Debug)]
pub struct Variant {
    /// The serde variant name.
    pub name: &'static str,
    pub words: Option<&'static str>,
    pub aliases: &'static [&'static str],
    /// `#[default]` — what `delete` resets a non-optional field to.
    pub default: bool,
    pub payload: Payload,
}

#[derive(Debug)]
pub enum Kind {
    Str,
    Bool,
    /// An unsigned integer with this maximum.
    Uint(u64),
    Ipv4,
    IpAddr,
    IpNet,
    Tuple(&'static [fn() -> Kind]),
    Option(fn() -> Kind),
    List(fn() -> Kind),
    Struct(&'static Node),
    Enum(&'static [Variant]),
}

/// A schema type's place in the CLI tree. Implemented by `#[derive(Cli)]`
/// for schema structs and enums, and below for the leaf types they use.
pub trait CliValue {
    fn kind() -> Kind;
}

macro_rules! leaf {
    ($($t:ty => $k:expr),* $(,)?) => {
        $(impl CliValue for $t {
            fn kind() -> Kind {
                $k
            }
        })*
    };
}

leaf! {
    String => Kind::Str,
    bool => Kind::Bool,
    u8 => Kind::Uint(u8::MAX.into()),
    u16 => Kind::Uint(u16::MAX.into()),
    u32 => Kind::Uint(u32::MAX.into()),
    std::net::Ipv4Addr => Kind::Ipv4,
    std::net::IpAddr => Kind::IpAddr,
    ipnet::IpNet => Kind::IpNet,
    (u8, u8) => Kind::Tuple(&[<u8 as CliValue>::kind, <u8 as CliValue>::kind]),
}

impl<T: CliValue> CliValue for Option<T> {
    fn kind() -> Kind {
        Kind::Option(T::kind)
    }
}

impl<T: CliValue> CliValue for Vec<T> {
    fn kind() -> Kind {
        Kind::List(T::kind)
    }
}

/// A schema type's `Default`, as JSON — `Node::default` for derived structs.
pub fn default_json<T: Default + serde::Serialize>() -> Value {
    serde_json::to_value(T::default()).expect("a schema default serializes")
}

/// `PascalCase` → `kebab-case`, the default CLI word of an enum variant.
pub fn kebab(name: &str) -> String {
    let mut out = String::new();
    for (i, c) in name.chars().enumerate() {
        if c.is_ascii_uppercase() {
            if i > 0 {
                out.push('-');
            }
            out.push(c.to_ascii_lowercase());
        } else {
            out.push(if c == '_' { '-' } else { c });
        }
    }
    out
}

/// The JSON of the unit variant of enum `kind` spelled `word`.
pub fn enum_word(kind: &Kind, word: &str) -> Option<Value> {
    let Kind::Enum(variants) = kind else {
        return None;
    };
    variants
        .iter()
        .find(|v| {
            matches!(v.payload, Payload::Unit) && variant_spellings(v).iter().any(|s| s == word)
        })
        .map(|v| Value::String(v.name.to_string()))
}

/// `area_id` → `area-id`, a field name as a usage placeholder.
pub fn kebab_field(name: &str) -> String {
    name.replace('_', "-")
}

/// Every spelling of a variant, canonical first.
pub fn variant_spellings(v: &Variant) -> Vec<String> {
    let mut out: Vec<String> = v.words.map(str::to_string).into_iter().collect();
    out.push(kebab(v.name));
    out.extend(v.aliases.iter().map(|a| (*a).to_string()));
    out
}

/// Every spelling of a field, canonical first: `words`, the REST segment,
/// then the aliases.
pub fn field_spellings(f: &Field) -> Vec<String> {
    let is_list = matches!((f.kind)(), Kind::List(_));
    let mut out: Vec<String> = f.words.map(str::to_string).into_iter().collect();
    out.push(crate::config_path::field_segment(f.name, is_list));
    out.extend(f.aliases.iter().map(|a| (*a).to_string()));
    out
}

/// The root of the tree.
pub fn root() -> &'static Node {
    match <crate::Config as CliValue>::kind() {
        Kind::Struct(node) => node,
        _ => unreachable!("Config derives Cli as a struct"),
    }
}
